input.sparql:
SELECT ?p ?ts WHERE {
  ?p label "Perimeter_bot_ZN_2" .
  ?point brick:hasPointType ?t ; rdfs:label ?lbl .
  FILTER (lcases(?lbl) = "perimeter_bot_zn_2")
  .
  OPTIONAL { ?point ref:hasExternalReference/expression ?ref ; ref:hasTimeseriesId ?ts }
} LIMIT 10

SELECT ?p ?type ?ts WHERE {
  ?p a brick:Occupancy_Predictor .
  OPTIONAL { ?p brick:hasProperty ?prop }
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
} LIMIT 10

SELECT ?p ?type ?ts WHERE {
  ?p a brick:Occupancy .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
} LIMIT 20

SELECT ?p ?type ?ts WHERE {
  ?p a ?type .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
} LIMIT 200
